
#' Plot Two-Way Sensitivity Analysis Contours
#'
#' @description
#' Produces continuous-colour sensitivity surfaces with contour
#' lines from deterministic two-way sensitivity analysis results
#' generated by compute_twsa().
#'
#' For absolute NMB, the NMB = 0 decision boundary can be
#' highlighted to distinguish cost-effective and
#' non-cost-effective parameter combinations.
#'
#' @param data An object of class "twsa_result".
#' @param metric Economic outcome: "nmb", "icer",
#'   "delta_cost" or "delta_effect".
#' @param lambda Willingness-to-pay threshold for NMB.
#' @param impact_mode Either "absolute" or "relative".
#' @param mode Either "Overall" or "Subgroups".
#' @param facet_by Faceting directive.
#' @param plot_by Independent plot grouping directive.
#' @param filter_expr Optional filtering expression.
#' @param facet_scales Facet scaling behaviour.
#' @param palette Two colours defining the continuous scale.
#' @param midpoint Midpoint for the diverging colour scale.
#'   Defaults to zero for NMB and relative impacts.
#' @param midpoint_color Colour at the midpoint.
#' @param n_contours Number of contour intervals.
#' @param show_lines Display secondary contour lines.
#' @param show_boundary Highlight the NMB = 0 decision boundary.
#' @param boundary_color Colour of the decision boundary.
#' @param boundary_linewidth Width of the decision boundary.
#' @param return_data Return prepared plotting data.
#'
#' @details
#' The colour surface is constructed from the numerical TWSA
#' grid without assuming equal spacing between parameter levels.
#'
#' Contour lines are calculated from the evaluated grid using
#' ggplot2's contour algorithm.
#'
#' The NMB = 0 boundary is displayed only for absolute NMB.
#' It represents economic indifference between the intervention
#' and its comparator at the selected WTP threshold.
#'
#' Relative impacts represent deviations from the corresponding
#' baseline-baseline scenario and do not define an economic
#' decision boundary.
#'
#' @return A ggplot object, a cea_multplots collection,
#'   or prepared plotting data.
#'
#' @export
#' @rawNamespace export(plot.contour)
plot.contour <- function(
    data,
    metric = "nmb",
    lambda = NULL,
    impact_mode = "absolute",
    mode = "Overall",
    facet_by = NULL,
    plot_by = NULL,
    filter_expr = NULL,
    facet_scales = "free",
    palette = c(
      lower = "#C0504D",
      upper = "#4472C4"
    ),
    midpoint = NULL,
    midpoint_color = "#FFFFFF",
    n_contours = 12L,
    show_lines = TRUE,
    show_boundary = TRUE,
    boundary_color = "black",
    boundary_linewidth = 1.1,
    return_data = FALSE
) {

  `%||%` <- function(a, b) {
    if (!is.null(a)) a else b
  }

  # -----------------------------------------------------------------------
  # 1. Input validation
  # -----------------------------------------------------------------------

  if (!inherits(data, "twsa_result")) {
    stop("'data' must be a twsa_result object.")
  }

  metric <- match.arg(
    metric,
    c("nmb", "icer", "delta_cost", "delta_effect")
  )

  impact_mode <- match.arg(
    impact_mode,
    c("absolute", "relative")
  )

  mode <- match.arg(
    mode,
    c("Overall", "Subgroups")
  )

  allowed_facets <- c(
    "none", "dataset", "comparison", "pair",
    "subgroup", "subgroup_var", "subgroup_level"
  )

  allowed_plots <- c(
    "none", "dataset", "comparison", "pair",
    "subgroup_var", "subgroup_level"
  )

  validate_directive <- function(x, allowed, name) {

    if (is.null(x)) {
      return(invisible(TRUE))
    }

    if (!is.character(x) ||
        length(x) != 1L ||
        is.na(x) ||
        !x %in% allowed) {
      stop(
        "'", name, "' must be one of: ",
        paste(allowed, collapse = ", ")
      )
    }

    invisible(TRUE)
  }

  validate_directive(facet_by, allowed_facets, "facet_by")
  validate_directive(plot_by, allowed_plots, "plot_by")

  if (!is.character(facet_scales) ||
      length(facet_scales) != 1L ||
      is.na(facet_scales) ||
      !facet_scales %in% c(
        "fixed", "free", "free_x", "free_y"
      )) {
    stop("Invalid 'facet_scales'.")
  }

  if (!is.numeric(n_contours) ||
      length(n_contours) != 1L ||
      is.na(n_contours) ||
      !is.finite(n_contours) ||
      n_contours < 2L ||
      n_contours != floor(n_contours)) {
    stop("'n_contours' must be an integer >= 2.")
  }

  for (arg in c(
    "show_lines", "show_boundary", "return_data"
  )) {

    value <- get(arg)

    if (!is.logical(value) ||
        length(value) != 1L ||
        is.na(value)) {
      stop("'", arg, "' must be TRUE or FALSE.")
    }
  }

  if (!is.character(palette) ||
      length(palette) != 2L ||
      anyNA(palette)) {
    stop("'palette' must contain two colours.")
  }

  if (!is.character(midpoint_color) ||
      length(midpoint_color) != 1L ||
      is.na(midpoint_color)) {
    stop("'midpoint_color' must be a single colour.")
  }

  if (!is.null(midpoint) &&
      (!is.numeric(midpoint) ||
       length(midpoint) != 1L ||
       !is.finite(midpoint))) {
    stop("'midpoint' must be a finite numeric value.")
  }

  if (!is.character(boundary_color) ||
      length(boundary_color) != 1L ||
      is.na(boundary_color)) {
    stop("'boundary_color' must be a colour.")
  }

  if (!is.numeric(boundary_linewidth) ||
      length(boundary_linewidth) != 1L ||
      is.na(boundary_linewidth) ||
      !is.finite(boundary_linewidth) ||
      boundary_linewidth <= 0) {
    stop("'boundary_linewidth' must be positive.")
  }

  # -----------------------------------------------------------------------
  # 2. Resolve defaults
  # -----------------------------------------------------------------------

  resolved_plot <- plot_by %||% "pair"

  resolved_facet <- facet_by %||%
    if (mode == "Subgroups") "subgroup" else "pair"

  n_levels <- data$settings$n_levels %||% 3L

  if (!is.numeric(n_levels) ||
      length(n_levels) != 1L ||
      is.na(n_levels) ||
      !is.finite(n_levels) ||
      n_levels < 3L) {
    stop("Invalid TWSA grid resolution.")
  }

  if (n_levels < 5L && !return_data) {
    warning(
      "Contour plots based on fewer than five levels ",
      "may provide limited detail.",
      call. = FALSE
    )
  }

  # -----------------------------------------------------------------------
  # 3. Resolve economic metric
  # -----------------------------------------------------------------------

  if (metric == "nmb") {

    available_lambda <- data$settings$lambda

    if (!is.numeric(available_lambda) ||
        length(available_lambda) == 0L ||
        any(!is.finite(available_lambda))) {
      stop("No valid WTP thresholds available.")
    }

    if (is.null(lambda)) {

      if (length(available_lambda) != 1L) {
        stop(
          "Multiple WTP thresholds available. Specify 'lambda'."
        )
      }

      lambda <- available_lambda
    }

    if (!is.numeric(lambda) ||
        length(lambda) != 1L ||
        !is.finite(lambda) ||
        !lambda %in% available_lambda) {
      stop("Selected lambda is not available.")
    }

    metric_column <- paste0("NMB_", lambda)

  } else {

    metric_column <- metric

    if (!is.null(lambda)) {
      warning(
        "'lambda' is ignored for metric = '",
        metric, "'.",
        call. = FALSE
      )
    }
  }

  # -----------------------------------------------------------------------
  # 4. Extract and filter results
  # -----------------------------------------------------------------------

  df <- data$sensitivity_results

  required <- c(
    "dataset", "subgroup_var", "subgroup_level",
    "comparison", "pair_uid",
    "parameter_1", "parameter_2",
    "scenario_1", "scenario_2",
    "value_1", "value_2", metric_column
  )

  missing <- setdiff(required, names(df))

  if (length(missing) > 0L) {
    stop(
      "Missing TWSA columns: ",
      paste(missing, collapse = ", ")
    )
  }

  if (!is.null(filter_expr)) {

    if (!is.character(filter_expr) ||
        length(filter_expr) != 1L ||
        is.na(filter_expr) ||
        !nzchar(filter_expr)) {
      stop("'filter_expr' must be a non-empty string.")
    }

    df <- dplyr::filter(
      df,
      !!rlang::parse_expr(filter_expr)
    )
  }

  if (mode == "Overall") {

    df <- df[
      is.na(df$subgroup_var) |
        df$subgroup_var == "Overall",
      ,
      drop = FALSE
    ]

  } else {

    df <- df[
      !is.na(df$subgroup_var) &
        df$subgroup_var != "Overall",
      ,
      drop = FALSE
    ]
  }

  if (nrow(df) == 0L) {
    stop("No results available after filtering.")
  }

  df$pair <- paste(
    df$parameter_1,
    "vs",
    df$parameter_2
  )

  df$subgroup <- paste(
    df$subgroup_var,
    df$subgroup_level,
    sep = ": "
  )

  df$original_value <- df[[metric_column]]

  # -----------------------------------------------------------------------
  # 5. Calculate analytical baselines
  # -----------------------------------------------------------------------

  baseline_keys <- c(
    "dataset", "subgroup_var", "subgroup_level",
    "comparison", "pair_uid"
  )

  baselines <- df[
    df$scenario_1 == "baseline" &
      df$scenario_2 == "baseline",
    c(baseline_keys, "original_value"),
    drop = FALSE
  ]

  if (nrow(baselines) == 0L) {
    stop("No baseline-baseline scenarios available.")
  }

  if (anyDuplicated(baselines[baseline_keys])) {
    stop("Duplicated baseline combinations.")
  }

  names(baselines)[
    names(baselines) == "original_value"
  ] <- "baseline_value"

  df <- dplyr::left_join(
    df,
    baselines,
    by = baseline_keys
  )

  if (anyNA(df$baseline_value)) {
    stop("Missing analytical baseline values.")
  }

  df$plot_value <- if (impact_mode == "relative") {
    df$original_value - df$baseline_value
  } else {
    df$original_value
  }

  if (!is.numeric(df$value_1) ||
      !is.numeric(df$value_2) ||
      any(!is.finite(df$value_1)) ||
      any(!is.finite(df$value_2))) {
    stop("Invalid numerical parameter values.")
  }

  # -----------------------------------------------------------------------
  # 6. Prepare analytical identifiers
  # -----------------------------------------------------------------------

  make_key <- function(x, columns) {

    if (length(columns) == 0L) {
      return(rep("all", nrow(x)))
    }

    do.call(
      interaction,
      c(
        lapply(
          x[columns],
          function(z) {
            z <- as.character(z)
            z[is.na(z)] <- "<NA>"
            z
          }
        ),
        list(
          drop = TRUE,
          lex.order = TRUE
        )
      )
    )
  }

  # -----------------------------------------------------------------------
  # 7. Validate panel compatibility
  # -----------------------------------------------------------------------

  validate_panels <- function(plot_df) {

    panel_keys <- switch(
      resolved_facet,
      none = character(0),
      subgroup = c("subgroup_var", "subgroup_level"),
      resolved_facet
    )

    panels <- split(
      plot_df,
      make_key(plot_df, panel_keys),
      drop = TRUE
    )

    for (panel in panels) {

      axis_pairs <- unique(
        panel[c("parameter_1", "parameter_2")]
      )

      if (nrow(axis_pairs) > 1L) {
        stop(
          "Incompatible parameter axes within a contour panel. ",
          "Use plot_by = 'pair' or facet_by = 'pair'.",
          call. = FALSE
        )
      }

      analytical_series <- unique(
        panel[baseline_keys]
      )

      if (nrow(analytical_series) > 1L) {
        stop(
          "Multiple analytical surfaces overlap within a panel. ",
          "Separate datasets, comparisons or subgroups using ",
          "plot_by, facet_by or filter_expr.",
          call. = FALSE
        )
      }
    }

    invisible(TRUE)
  }

  # -----------------------------------------------------------------------
  # 8. Calculate cell boundaries
  # -----------------------------------------------------------------------

  compute_boundaries <- function(values) {

    values <- sort(unique(values))

    if (length(values) < 2L) {
      stop(
        "At least two distinct numerical parameter values ",
        "are required."
      )
    }

    midpoints <- (
      values[-1L] +
        values[-length(values)]
    ) / 2

    data.frame(
      value = values,
      lower = c(values[1L], midpoints),
      upper = c(midpoints, values[length(values)])
    )
  }

  prepare_surface <- function(plot_df) {

    grid_keys <- baseline_keys

    grid_groups <- split(
      plot_df,
      make_key(plot_df, grid_keys),
      drop = TRUE
    )

    surface_parts <- lapply(
      grid_groups,
      function(g) {

        if (anyDuplicated(g[c("value_1", "value_2")])) {
          stop("Duplicated numerical grid coordinates.")
        }

        nx <- length(unique(g$value_1))
        ny <- length(unique(g$value_2))

        if (nx < 2L || ny < 2L) {
          stop("Insufficient grid resolution for contours.")
        }

        if (nrow(g) != nx * ny) {
          stop("Incomplete numerical grid for contours.")
        }

        x_bounds <- compute_boundaries(g$value_1)
        y_bounds <- compute_boundaries(g$value_2)

        x_index <- match(
          g$value_1,
          x_bounds$value
        )

        y_index <- match(
          g$value_2,
          y_bounds$value
        )

        g$xmin <- x_bounds$lower[x_index]
        g$xmax <- x_bounds$upper[x_index]

        g$ymin <- y_bounds$lower[y_index]
        g$ymax <- y_bounds$upper[y_index]

        g
      }
    )

    dplyr::bind_rows(surface_parts)
  }

  # -----------------------------------------------------------------------
  # 9. Prepare metric labels
  # -----------------------------------------------------------------------

  metric_title <- switch(
    metric,
    nmb = "Net Monetary Benefit",
    icer = "Incremental Cost-Effectiveness Ratio",
    delta_cost = "Incremental Cost",
    delta_effect = "Incremental Effectiveness"
  )

  legend_label <- switch(
    metric,
    nmb = "NMB",
    icer = "ICER",
    delta_cost = "\u0394 Cost",
    delta_effect = "\u0394 Effect"
  )

  resolved_midpoint <- midpoint %||%
    if (
      metric == "nmb" ||
      impact_mode == "relative"
    ) {
      0
    } else {
      NULL
    }

  # -----------------------------------------------------------------------
  # 10. Build contour plot
  # -----------------------------------------------------------------------

  build_plot <- function(plot_df, plot_label = NULL) {

    validate_panels(plot_df)

    plot_df <- prepare_surface(plot_df)

    if (!any(is.finite(plot_df$plot_value))) {
      stop("No finite economic values available.")
    }

    plot_df$contour_group <- as.integer(
      make_key(plot_df, baseline_keys)
    )

    pair_names <- unique(plot_df$pair_uid)

    if (length(pair_names) == 1L) {

      x_label <- unique(plot_df$parameter_1)[1]
      y_label <- unique(plot_df$parameter_2)[1]

    } else {

      x_label <- "Parameter 1"
      y_label <- "Parameter 2"
    }

    # ---------------------------------------------------------------------
    # Continuous colour surface
    # ---------------------------------------------------------------------

    p <- ggplot2::ggplot(
      plot_df,
      ggplot2::aes(
        x = value_1,
        y = value_2,
        z = plot_value,
        group = contour_group
      )
    ) +
      ggplot2::geom_rect(
        ggplot2::aes(
          xmin = xmin,
          xmax = xmax,
          ymin = ymin,
          ymax = ymax,
          fill = plot_value
        ),
        inherit.aes = FALSE,
        colour = NA
      )

    # ---------------------------------------------------------------------
    # Colour scale
    # ---------------------------------------------------------------------

    if (is.null(resolved_midpoint)) {

      p <- p +
        ggplot2::scale_fill_gradient(
          low = unname(palette[1]),
          high = unname(palette[2]),
          name = legend_label,
          na.value = "grey85",
          guide = ggplot2::guide_colorbar(
            barheight = grid::unit(65, "mm"),
            barwidth = grid::unit(5, "mm")
          )
        )

    } else {

      p <- p +
        ggplot2::scale_fill_gradient2(
          low = unname(palette[1]),
          mid = midpoint_color,
          high = unname(palette[2]),
          midpoint = resolved_midpoint,
          name = legend_label,
          na.value = "grey85",
          guide = ggplot2::guide_colorbar(
            barheight = grid::unit(65, "mm"),
            barwidth = grid::unit(5, "mm")
          )
        )
    }

    # ---------------------------------------------------------------------
    # Secondary contour lines
    # ---------------------------------------------------------------------

    if (show_lines) {

      p <- p +
        ggplot2::geom_contour(
          ggplot2::aes(
            x = value_1,
            y = value_2,
            z = plot_value,
            group = contour_group
          ),
          colour = "grey35",
          linewidth = 0.3,
          bins = n_contours,
          na.rm = TRUE
        )
    }

    # ---------------------------------------------------------------------
    # Economic decision boundary
    # ---------------------------------------------------------------------

    eligible_boundary <- (
      metric == "nmb" &&
        impact_mode == "absolute" &&
        show_boundary
    )

    if (eligible_boundary) {

      grid_groups <- split(
        plot_df,
        make_key(plot_df, baseline_keys),
        drop = TRUE
      )

      has_boundary <- any(
        vapply(
          grid_groups,
          function(g) {

            z <- g$plot_value
            z <- z[is.finite(z)]

            length(z) > 0L &&
              min(z) < 0 &&
              max(z) > 0
          },
          logical(1)
        )
      )

      if (has_boundary) {

        p <- p +
          ggplot2::geom_contour(
            ggplot2::aes(
              x = value_1,
              y = value_2,
              z = plot_value,
              group = contour_group
            ),
            breaks = 0,
            colour = boundary_color,
            linewidth = boundary_linewidth,
            na.rm = TRUE
          )
      }
    }

    # ---------------------------------------------------------------------
    # Faceting
    # ---------------------------------------------------------------------

    if (resolved_facet == "subgroup") {

      p <- p +
        ggplot2::facet_grid(
          rows = ggplot2::vars(subgroup_level),
          cols = ggplot2::vars(subgroup_var),
          scales = facet_scales
        )

    } else if (
      resolved_facet != "none" &&
      !(resolved_facet == "pair" &&
        length(pair_names) == 1L)
    ) {

      p <- p +
        ggplot2::facet_wrap(
          ggplot2::vars(
            !!rlang::sym(resolved_facet)
          ),
          scales = facet_scales
        )
    }

    # ---------------------------------------------------------------------
    # Titles
    # ---------------------------------------------------------------------

    subtitle <- paste0(
      metric_title,
      if (impact_mode == "relative") {
        " - Change from baseline"
      } else {
        " - Absolute values"
      }
    )

    if (metric == "nmb") {

      subtitle <- paste0(
        subtitle,
        " | WTP = ",
        format(
          lambda,
          big.mark = ",",
          scientific = FALSE,
          trim = TRUE
        ),
        "/QALY"
      )
    }

    if (!is.null(plot_label)) {
      subtitle <- paste0(
        subtitle,
        "\n",
        plot_label
      )
    }

    # ---------------------------------------------------------------------
    # Final presentation
    # ---------------------------------------------------------------------

    p <- p +
      ggplot2::labs(
        title = "Two-Way Sensitivity Analysis",
        subtitle = subtitle,
        x = x_label,
        y = y_label
      ) +
      ggplot2::coord_cartesian(
        expand = FALSE
      ) +
      ggplot2::theme_bw() +
      ggplot2::theme(
        panel.grid.major = ggplot2::element_blank(),
        panel.grid.minor = ggplot2::element_blank(),
        strip.background = ggplot2::element_rect(
          fill = "grey92",
          colour = NA
        ),
        strip.text = ggplot2::element_text(
          face = "bold"
        ),
        plot.title = ggplot2::element_text(
          face = "bold",
          size = 13
        ),
        plot.subtitle = ggplot2::element_text(
          size = 10,
          lineheight = 1.2
        ),
        legend.title = ggplot2::element_text(
          face = "bold"
        )
      )

    return(p)
  }

  # -----------------------------------------------------------------------
  # 11. Return data
  # -----------------------------------------------------------------------

  if (return_data && resolved_plot == "none") {
    return(df)
  }

  # -----------------------------------------------------------------------
  # 12. Single plot
  # -----------------------------------------------------------------------

  if (resolved_plot == "none") {
    return(build_plot(df))
  }

  # -----------------------------------------------------------------------
  # 13. Independent plots
  # -----------------------------------------------------------------------

  plot_levels <- sort(
    unique(as.character(df[[resolved_plot]]))
  )

  output <- vector(
    "list",
    length(plot_levels)
  )

  names(output) <- plot_levels

  for (level in plot_levels) {

    plot_df <- df[
      as.character(df[[resolved_plot]]) == level,
      ,
      drop = FALSE
    ]

    output[[level]] <- if (return_data) {

      plot_df

    } else {

      build_plot(
        plot_df,
        plot_label = level
      )
    }
  }

  # -----------------------------------------------------------------------
  # 14. Shared multiple-plots handler
  # -----------------------------------------------------------------------

  if (!return_data) {

    output <- cea_multplots_handler(
      output,
      plot_type = "TWSA contour"
    )
  }

  return(output)
}
